<script setup lang="ts">
import { ref } from 'vue'; import { useRouter } from 'vue-router'; import AuthShell from '@/layouts/AuthShell.vue'; import { useSessionStore } from '@/stores/session'; import { friendlyError } from '@/services/errors'
const code=ref(''),recovery=ref(''),mode=ref<'code'|'recovery'>('code'),error=ref(''),busy=ref(false),router=useRouter(),session=useSessionStore()
async function submit(){error.value='';busy.value=true;try{await session.verify(mode.value==='code'?code.value:'',mode.value==='recovery'?recovery.value:'');router.push('/')}catch(e){error.value=friendlyError(e,'Código inválido.')}finally{busy.value=false}}
</script>
<template><AuthShell><div class="auth-title"><h1>Confirme seu acesso</h1><p>Use o código exibido no seu aplicativo autenticador.</p></div><div v-if="error" class="alert error">{{error}}</div><form class="form-stack" @submit.prevent="submit"><label v-if="mode==='code'" class="field"><span>Código de 6 dígitos</span><input v-model="code" class="otp-input" inputmode="numeric" maxlength="6" placeholder="000000" @input="code=code.replace(/\D/g,'').slice(0,6)" autofocus/></label><label v-else class="field"><span>Código de recuperação</span><input v-model="recovery" autocomplete="one-time-code"/></label><button class="btn primary full" :disabled="busy">{{busy?'Verificando...':'Continuar'}}</button><button type="button" class="text-button" @click="mode=mode==='code'?'recovery':'code'">{{mode==='code'?'Usar código de recuperação':'Usar aplicativo autenticador'}}</button></form></AuthShell></template>
